    var bUp = remap(g('BrowsUp' + u), 0.12, 0.65);
    var bDown = remap(g('BrowsDown' + u), 0.12, 0.65);
    var smile = remap(g('MouthSmile' + u), 0.12, 0.70);
    var frown = remap(g('MouthFrown' + u), 0.12, 0.65);
    var sneer = remap(g('Sneer' + u), 0.15, 0.65);
    var lookUp = remap(g('EyeUp' + u), 0.05, 0.5), lookDown = remap(g('EyeDown' + u), 0.05, 0.5);
